/* @component: .gallery--slider */
(function () {
  const galleries = document.querySelectorAll('.gallery--slider');

  galleries.forEach(gallery => {
    let swiper = null;

    const btns = gallery.querySelectorAll('.filter-btn');
    const sourceItems = gallery.querySelectorAll('.gallery-source .gallery-item');
    const swiperWrap = gallery.querySelector('.swiper-wrapper');
    const nextBtn = gallery.querySelector('.ms-next');
    const prevBtn = gallery.querySelector('.ms-prev');

    const initSwiper = () => {
      if (typeof Swiper !== 'undefined') {
        if (swiper) { swiper.destroy(true, true); }

        swiper = new Swiper(gallery.querySelector('.ms-swiper-container'), {
          navigation: { nextEl: nextBtn, prevEl: prevBtn },
          // Добавлен блок пагинации
          pagination: {
            el: gallery.querySelector('.swiper-pagination'),
            clickable: true,
          },
          observer: true,
          observeParents: true,
          spaceBetween: 30,
          slidesPerView: 1,
          breakpoints: {
            640: {
              slidesPerView: 2,
              spaceBetween: 20
            },
            1024: {
              slidesPerView: 3,
              spaceBetween: 30
            },
            1200: {
              slidesPerView: 4,
              spaceBetween: 30
            }
          }
        });
      } else {
        setTimeout(initSwiper, 200);
      }
    };

    const updateSlider = (filterValue) => {
      swiperWrap.innerHTML = '';

      const filtered = Array.from(sourceItems).filter(item => {
        return filterValue === 'all' || item.getAttribute('data-category') === filterValue;
      });

      filtered.forEach(item => {
        const slide = document.createElement('div');
        slide.classList.add('swiper-slide');

        const imgHtml = item.querySelector('.is').innerHTML;
        const titleText = item.querySelector('h3') ? item.querySelector('h3').innerText : '';

        slide.innerHTML = `
          <div class="gallery-img">
            <div class="is">${imgHtml}</div>
          </div>
          <div class="gallery-info">
            <h3>${titleText}</h3>
          </div>
        `;
        swiperWrap.appendChild(slide);
      });

      const showNav = filtered.length > 1;
      nextBtn.style.display = prevBtn.style.display = showNav ? 'flex' : 'none';

      if (!swiper) {
        initSwiper();
      } else {
        swiper.update();
        swiper.slideTo(0, 0);
      }
    };

    btns.forEach(btn => {
      btn.addEventListener('click', () => {
        btns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const filterValue = btn.getAttribute('data-filter');
        updateSlider(filterValue);
      });
    });

    const defaultActive = gallery.querySelector('.filter-btn.active');
    const initialFilter = defaultActive ? defaultActive.getAttribute('data-filter') : 'all';
    updateSlider(initialFilter);
  });

  if (!document.getElementById('swiper-css')) {
    const l = document.createElement('link'); l.id = 'swiper-css'; l.rel = 'stylesheet';
    l.href = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css'; document.head.appendChild(l);
  }
  if (!document.getElementById('swiper-js')) {
    const s = document.createElement('script'); s.id = 'swiper-js';
    s.src = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js'; document.head.appendChild(s);
  }
})();
